<?php
declare(strict_types=1);

$root = dirname(__DIR__);
$payload = '';
$decoded = base64_decode( $payload, true );
if ( false === $decoded ) {
    throw new RuntimeException( 'Could not decode localization payload.' );
}
$decoded = gzdecode( $decoded );
if ( false === $decoded ) {
    throw new RuntimeException( 'Could not decompress localization payload.' );
}

$temp = __DIR__ . '/.l10n-delta.php';
if ( false === file_put_contents( $temp, $decoded ) ) {
    throw new RuntimeException( 'Could not materialize localization delta.' );
}
$delta = require $temp;
unlink( $temp );
if ( ! is_array( $delta ) || ! isset( $delta['remove'], $delta['add'] ) ) {
    throw new RuntimeException( 'Invalid localization delta.' );
}

function cb_l10n_quote( string $value ): string {
    return "'" . str_replace( [ '\\', "'" ], [ '\\\\', "\\'" ], $value ) . "'";
}

$locales = [ 'nl_NL', 'de_DE', 'fr_FR', 'es_ES', 'it_IT', 'pt_PT' ];
foreach ( $locales as $locale ) {
    $path = $root . '/languages/core-blueprint-' . $locale . '.l10n.php';
    $text = file_get_contents( $path );
    if ( false === $text ) {
        throw new RuntimeException( "Could not read {$locale} catalog." );
    }

    $lines = preg_split( '/(?<=\\n)/', $text );
    if ( false === $lines ) {
        throw new RuntimeException( "Could not split {$locale} catalog." );
    }

    foreach ( $delta['remove'] as $obsolete ) {
        $prefix = '        ' . cb_l10n_quote( (string) $obsolete ) . ' => ';
        $found = false;
        foreach ( $lines as $index => $line ) {
            if ( str_starts_with( $line, $prefix ) ) {
                unset( $lines[ $index ] );
                $found = true;
                break;
            }
        }
        if ( ! $found ) {
            throw new RuntimeException( "Obsolete {$locale} key not found: {$obsolete}" );
        }
    }

    $text = implode( '', $lines );
    $marker = "    ],\n];\n";
    $position = strrpos( $text, $marker );
    if ( false === $position ) {
        throw new RuntimeException( "Could not locate {$locale} messages boundary." );
    }

    $insert = '';
    foreach ( $delta['add'][ $locale ] ?? [] as $key => $translation ) {
        $insert .= '        ' . cb_l10n_quote( (string) $key ) . ' => ' . cb_l10n_quote( (string) $translation ) . ",\n";
    }
    $text = substr( $text, 0, $position ) . $insert . substr( $text, $position );

    if ( false === file_put_contents( $path, $text ) ) {
        throw new RuntimeException( "Could not write {$locale} catalog." );
    }

    $catalog = require $path;
    if ( ! is_array( $catalog ) || 3344 !== count( $catalog['messages'] ?? [] ) ) {
        throw new RuntimeException( "Unexpected {$locale} catalog size after synchronization." );
    }
    foreach ( $delta['remove'] as $obsolete ) {
        if ( array_key_exists( (string) $obsolete, $catalog['messages'] ) ) {
            throw new RuntimeException( "Obsolete {$locale} key survived synchronization: {$obsolete}" );
        }
    }
    foreach ( $delta['add'][ $locale ] as $key => $translation ) {
        if ( ( $catalog['messages'][ $key ] ?? null ) !== $translation ) {
            throw new RuntimeException( "{$locale} translation mismatch after synchronization: {$key}" );
        }
    }
}

@unlink( __FILE__ );
@unlink( $root . '/.github/workflows/l10n-materialize.yml' );

echo "Localization catalogs materialized successfully.\n";
